output_text:
[
  {
    "id": "no_carts_single_file",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "narrow_horizontal_passage": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "narrow_horizontal_passage",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_push_into_canyon",
    "text": "Agents must not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_with_cart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_shelf_aisle_with_cart"
    }
  },
  {
    "id": "hand_carry_in_canyon",
    "text": "Items located in single-file shelf aisles must be handled without the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "single_file_shelf_interaction": {
          "pre": {
            "and": [
              "single_file_shelf_aisle",
              "adjShelf",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "single_file_shelf_interaction",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "reclaim_after_canyon",
    "text": "After entering a single-file shelf aisle without the cart, the agent is obliged to reclaim the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "single_file_shelf_aisle",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "cart_bay_first",
    "text": "At the start of the trip, the agent is obliged to take a cart from the cart bay.",
    "abstraction": {
      "state_properties": {
        "cart_bay": "at(1,7)",
        "entrance_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        }
      },
      "events": {
        "take_cart_from_bay": {
          "pre": {
            "and": [
              "cart_bay",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_bay"
    }
  },
  {
    "id": "cartless_only_for_canyon_trip",
    "text": "Moving without a cart is prohibited except in the entrance area or as part of a cartless trip into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "entrance_area": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        }
      },
      "events": {
        "enter_single_file_shelf_aisle_without_cart": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "single_file_shelf_aisle"
          },
          {
            "not": "entrance_area"
          },
          {
            "not": "enter_single_file_shelf_aisle_without_cart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_for_open_shelf_service",
    "text": "Shelf interactions from open shopping aisles must be done while holding the cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "open_shelf_service_point": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {
        "open_shelf_interaction": {
          "pre": {
            "and": [
              "open_shelf_service_point",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "open_shelf_interaction",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_only_wide_cross_aisle",
    "text": "If the cart is parked, it must be parked only in a wide cross-aisle rather than beside shelves or in a narrow passage.",
    "abstraction": {
      "state_properties": {
        "wide_cross_aisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "park_cart",
          {
            "not": "wide_cross_aisle"
          }
        ]
      }
    }
  }
]
